questionvariables.text:
funcidx : rand(3);                    /* 0 arcsin, 1 arccos, 2 arctan */
invname : if funcidx=0 then "sin^{-1}" elseif funcidx=1 then "cos^{-1}" else "tan^{-1}";
signidx : rand(2);                     /* 0 = positive input, 1 = negative input (not available for arccos in this simple set) */
baseidx : rand_with_prohib(1,3,[]);     /* which of a small standard-value table to use */
/* standard values, kept simple: use k = pi/6, pi/4, pi/3 as principal outputs for POSITIVE inputs */
basepi : [1/6,1/4,1/3][baseidx];
val_pos : if funcidx=0 then (if baseidx=1 then 1/2 elseif baseidx=2 then sqrt(2)/2 else sqrt(3)/2)
          elseif funcidx=1 then (if baseidx=1 then sqrt(3)/2 elseif baseidx=2 then sqrt(2)/2 else 1/2)
          else (if baseidx=1 then 1/sqrt(3) elseif baseidx=2 then 1 else sqrt(3));
usesign : if funcidx=1 then 0 else signidx;   /* keep arccos example with a positive input only, for simplicity */
val : if usesign=1 then -val_pos else val_pos;
/* principal value ranges: arcsin in [-pi/2,pi/2], arccos in [0,pi], arctan in (-pi/2,pi/2) */
ta : if funcidx=0 then (if usesign=1 then -basepi*%pi else basepi*%pi)
     elseif funcidx=1 then (if usesign=1 then %pi-basepi*%pi else basepi*%pi)
     else (if usesign=1 then -basepi*%pi else basepi*%pi);
/* common mistake: giving a coterminal / out-of-principal-range angle instead */
wrong_outofrange : if funcidx=0 then (if usesign=1 then %pi+basepi*%pi else %pi-basepi*%pi)
                    elseif funcidx=1 then (if usesign=1 then -( %pi-basepi*%pi) else -basepi*%pi)
                    else (if usesign=1 then %pi-basepi*%pi else %pi+basepi*%pi);
